SELECT id, service, host, log_ts, latency_ms, status_code, payload_json, context, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, COALESCE(context['trace'], 'none') AS trace_or_default, context['version'] AS version, COALESCE(context['version'], 'none') AS version_or_default, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text FROM app_logs WHERE host NOT IN ('h4', 'h3', 'h1');
